{
  "name": "tool_execute",
  "description": "Execute one discovered enabled tool with its exact arguments. Uses the same validation, rate limits, trace and permissions as calling that tool directly, and preserves its visualization. Call tool_describe first. Cannot recursively call discovery dispatchers.",
  "group": "catalog",
  "origin": "built-in",
  "execution": {
    "protocol": "dt.tool/v1",
    "transport": "in-process"
  },
  "inputSchema": {
    "type": "object",
    "properties": {
      "name": {
        "type": "string",
        "description": "Exact enabled tool name"
      },
      "arguments": {
        "type": "object",
        "additionalProperties": true,
        "description": "Arguments conforming to tool_describe inputSchema"
      }
    },
    "required": [
      "name",
      "arguments"
    ]
  }
}
